            try
            {

                int i = 0;
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;

                    if (ilist.is_default == "1")
                    {
                        cmd.CommandText = "update CompanyMaster set is_default = '0' where UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " ";
                        con.Open();
                        i = cmd.ExecuteNonQuery();
                        cmd.Dispose();
                        con.Close();
                    }

                    cmd.CommandType = System.Data.CommandType.Text;
                    cmd.CommandText = "Insert Into CompanyMaster  (CompanyName, MobileNo, AlterMobileNo, Email, BusinessAddress, GSTIN, State, BusinessType, BusinessCategory, BusinessDescription, BankName, ACNo, IFSC, CompanyLogo, Sign, is_default, UserAccountId) Values " +
                                    " ('" + ilist.CompanyName + "', '" + ilist.MobileNo + "' , '" + ilist.AlterMobileNo + "' , '" + ilist.Email + "', '" + ilist.BusinessAddress + "', '" + ilist.GSTIN + "', '" + ilist.State + "', '" + ilist.BusinessType + "', '" + ilist.BusinessCategory + "', '" + ilist.BusinessDescription + "', '" + ilist.BankName + "', '" + ilist.ACNo + "', '" + ilist.IFSC + "', '" + imagePath + "', '" + Signature + "', '" + ilist.is_default + "', " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " )";
                    con.Open();
                    i = cmd.ExecuteNonQuery();
                    cmd.Dispose();
                    con.Close();

                    if (i > 0)
                    {
                        comman.Code = 201;
                        comman.Message = "Record has been saved successfully.";
                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Problem has been occurred while submitting your data.";
                    }
                }


            }
            catch (SqlException ex)
            {
                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";

                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }

            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }




        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getCompanyMasterById(string id)
        {
            JavaScriptSerializer js;
            List<CompanyMaster> listUser = new List<CompanyMaster>();
            CompanyMasterResponse response = new CompanyMasterResponse();

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = "select CM.*, POS.StateTitle from CompanyMaster CM" +
                    "  LEFT JOIN PlaceOfSupplyMaster POS ON CM.State = POS.GSTStateCode" +
                    "  where CM.CompanyId = " + id;
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {

                        CompanyMaster condition = new CompanyMaster();
                        condition.CompanyId = Convert.ToInt32(rdr["CompanyId"].ToString());
                        condition.CompanyName = rdr["CompanyName"].ToString();
                        condition.MobileNo = rdr["MobileNo"].ToString();
                        condition.AlterMobileNo = rdr["AlterMobileNo"].ToString();
                        condition.Email = rdr["Email"].ToString();
                        condition.BusinessAddress = rdr["BusinessAddress"].ToString();

                        condition.GSTIN = rdr["GSTIN"].ToString();
                        condition.State = rdr["State"].ToString();
                        condition.StateTitle = rdr["StateTitle"].ToString();
                        condition.BusinessType = rdr["BusinessType"].ToString();
                        condition.BusinessCategory = rdr["BusinessCategory"].ToString();
                        condition.BusinessDescription = rdr["BusinessDescription"].ToString();

                        condition.BankName = rdr["BankName"].ToString();
                        condition.ACNo = rdr["ACNo"].ToString();
                        condition.IFSC = rdr["IFSC"].ToString();
                        condition.CompanyLogo = rdr["CompanyLogo"].ToString();
                        condition.Sign = rdr["Sign"].ToString();
                        condition.is_default = rdr["is_default"].ToString();
                        condition.SupportNumber = rdr["SupportNumber"].ToString();


                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 200;
            response.Message = "Success";
            response.listCompanyMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }



