            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = " select * " +
                    " from DesignerMaster where DesignerID = " + ilist.DesignerID + "";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    string photo = "";

                    while (rdr.Read())
                    {
                        photo = rdr["AadharUpload"].ToString();
                    }

                    string path = Server.MapPath(@"" + photo);
                    FileInfo filess = new FileInfo(path);
                    if (filess.Exists)
                    {
                        filess.Delete();
                    }

                    rdr.Close();
                    cmd.Dispose();
                    con.Close();

                    try
                    {
                        cmd.Connection = con;
                        cmd.CommandText = "DELETE FROM DesignerMaster WHERE DesignerID = " + ilist.DesignerID + " ";
                        con.Open();
                        int i = cmd.ExecuteNonQuery();
                        con.Close();
                        if (i > 0)
                        {
                            comman.Code = 200;
                            comman.Message = "Record Deleted Successfully.";
