                        string sql = String.Format("Update LocationMaster set LocationTitle = @LocationTitle, LocationAddress = @LocationAddress, IsActive = '" + ilist.IsActive + "', UserAccountId = '" + ilist.UserAccountId + "', CompanyId = '" + ilist.CompanyId + "' where " +
