            ilist.ProductSrNo = HttpContext.Current.Request.Params["PostQueue"];
            //ilist.image_isActive = HttpContext.Current.Request.Params["image_isActive"];


            string[] PostQueue = ilist.ProductSrNo.Split('|');

            var Onepost_type_id = PostQueue[0].Split(',')[0];
            var OneQueue = PostQueue[0].Split(',')[1];

            var Twopost_type_id = PostQueue[1].Split(',')[0];
            var TwoQueue = PostQueue[1].Split(',')[1];

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection conn = new SqlConnection(cs))
            {

                SqlCommand cmd = new SqlCommand();

                cmd.Connection = conn;
                cmd.CommandText = "update DesignSpecificationMaster set Position = " + TwoQueue + " where DesignSpecificationID = " + Onepost_type_id + "";
                conn.Open();
                int i = cmd.ExecuteNonQuery();
                conn.Close();
                if (i > 0)
                {

                    cmd.Connection = conn;
                    cmd.CommandText = "update DesignSpecificationMaster set Position = " + OneQueue + " where DesignSpecificationID = " + Twopost_type_id + "";
                    conn.Open();
                    int j = cmd.ExecuteNonQuery();
                    conn.Close();

                    if (j > 0)
