        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignCategoryMaster()
        {

            JavaScriptSerializer js;
            List<DesignCategoryMaster> listUser = new List<DesignCategoryMaster>();
            DesignCategoryMasterResponse response = new DesignCategoryMasterResponse();

            var request = HttpContext.Current.Request;
            DesignCategoryMaster ilist = new DesignCategoryMaster();

            ilist.searchDesignCategory = HttpContext.Current.Request.Params["searchDesignCategory"];
            ilist.startFrom = HttpContext.Current.Request.Params["startFrom"];



            if (ilist.searchDesignCategory != "")
            {
                ilist.searchDesignCategory = " where  " +
                    " DesignCategory LIKE '%" + ilist.searchDesignCategory + "%' ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = "select * " +
                    "from DesignCategoryMaster " + ilist.searchDesignCategory + "" +
                    "order by Position desc" +
                " OFFSET " + ilist.startFrom + " ROWS FETCH NEXT 10 ROWS ONLY ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        DesignCategoryMaster condition = new DesignCategoryMaster();
                        condition.DesignCategoryID = Convert.ToInt32(rdr["DesignCategoryID"].ToString());
                        condition.IsActive = Convert.ToInt32(rdr["IsActive"].ToString());
