        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertYarnMaterialMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

            var request = HttpContext.Current.Request;

            CommanResponse comman = new CommanResponse();
            YarnMaterialMaster ilist = new YarnMaterialMaster();
            ilist.YarnMaterial = HttpContext.Current.Request.Params["YarnMaterial"];
            ilist.Denier = HttpContext.Current.Request.Params["Denier"];
            ilist.HSNCode = HttpContext.Current.Request.Params["HSNCode"];
            ilist.UnitId = Convert.ToInt32(HttpContext.Current.Request.Params["UnitId"]);
            ilist.GSTSLABId = Convert.ToInt32(HttpContext.Current.Request.Params["GSTSLABId"]);
            ilist.IsActive = Convert.ToInt32(HttpContext.Current.Request.Params["IsActive"]);
            ilist.UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
            ilist.CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);

            try
            {

                int i = 0;
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;

                    cmd.CommandType = System.Data.CommandType.Text;
                    cmd.CommandText = "Select TOP 1 (ISNULL(Position,0) + 1) as Position from YarnMaterialMaster order by Position desc ";
                    con.Open();
                    SqlDataReader rdr = cmd.ExecuteReader();
                    int Position = 1;
                    if (rdr.Read())
                    {
                        Position = Convert.ToInt32(rdr["Position"].ToString());
                        //cmd.Dispose();
                        //con.Close();
                    }

                    rdr.Close();
                    cmd.CommandType = System.Data.CommandType.Text;
                    string sql = String.Format("Insert Into YarnMaterialMaster  (DateAndTime,YarnMaterial, Denier, UnitId, HSNCode, GSTSLABId, IsActive, Position, CompanyId, UserAccountId) Values " +
                                    " ('" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', @YarnMaterial, @Denier, '" + ilist.UnitId + "', '" + ilist.HSNCode + "', '" + ilist.GSTSLABId + "', '" + ilist.IsActive + "', '" + Position + "', '" + ilist.CompanyId + "', '" + ilist.UserAccountId + "')");

                    cmd.CommandText = sql;
                    cmd.Parameters.Add("@YarnMaterial", SqlDbType.NVarChar).Value = ilist.YarnMaterial;
                    cmd.Parameters.Add("@Denier", SqlDbType.NVarChar).Value = ilist.Denier;

                    i = cmd.ExecuteNonQuery();


                    cmd.Dispose();
                    con.Close();


                    if (i > 0)
                    {
                        comman.Code = 201;
                        comman.Message = "Yarn Material has been saved successfully.";
                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "This Yarn Material is already Exists.";
                    }
                }


            }
            catch (SqlException ex)
            {
                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";

                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }


