        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertFinancialYearMaster()
        {
            JavaScriptSerializer js;
            List<FinancialYearMaster> listUser = new List<FinancialYearMaster>();
            FinancialYearMasterResponce response = new FinancialYearMasterResponce();

            FinancialYearMaster ilist = new FinancialYearMaster();
            CommanResponse comman = new CommanResponse();

            ilist.FinancialYear = HttpContext.Current.Request.Params["FinancialYear"];
            ilist.AssessmentYear = HttpContext.Current.Request.Params["AssessmentYear"];
            ilist.StartDate = Convert.ToDateTime(HttpContext.Current.Request.Params["StartDate"]);
            ilist.EndDate = Convert.ToDateTime(HttpContext.Current.Request.Params["EndDate"]);
            ilist.IsDefault = Convert.ToInt32(HttpContext.Current.Request.Params["IsDefault"]);


            try
            {

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;
                    cmd.CommandType = System.Data.CommandType.Text;
                    cmd.CommandText = " select * " +
                        " from FinancialYearMaster where FinancialYear = '" + ilist.FinancialYear + "' ";
                    con.Open();
                    SqlDataReader rdr = cmd.ExecuteReader();

                    if (rdr.HasRows)
                    {
                        rdr.Close();
                        cmd.Dispose();
                        con.Close();

                        comman.Code = 500;
                        comman.Message = "Can't submit this year because this year already exists.";
                        js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;

                    }
                    else
                    {
                        rdr.Close();
                        cmd.Dispose();
                        con.Close();

                        try
                        {
                            cmd.Connection = con;

                            if (ilist.IsDefault == 1)
                            {
                                cmd.CommandText = "update FinancialYearMaster set IsDefault = '0'";
                                con.Open();
                                cmd.ExecuteNonQuery();
                                con.Close();
                            }

                            cmd.CommandText = "Insert Into FinancialYearMaster  (FinancialYear, AssessmentYear, StartDate, EndDate, IsDefault) Values " +
                                                    " ('" + ilist.FinancialYear + "','" + ilist.AssessmentYear + "', '" + Convert.ToDateTime(ilist.StartDate).ToString("yyyy-MM-dd") + "', '" + Convert.ToDateTime(ilist.EndDate).ToString("yyyy-MM-dd") + "', '" + ilist.IsDefault + "' )";

                            con.Open();
                            int i = cmd.ExecuteNonQuery();
                            con.Close();
                            if (i > 0)
                            {
                                comman.Code = 201;
                                comman.Message = "Record has been saved successfully.";
                                js = new JavaScriptSerializer();
                                js.MaxJsonLength = Int32.MaxValue;
                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }
                            else
                            {
                                comman.Code = 0;
                                comman.Message = "Problem has been occurred while submitting your data.";
                                js = new JavaScriptSerializer();
                                js.MaxJsonLength = Int32.MaxValue;
                                Context.Response.Write(js.Serialize(comman));
                                return;
                            }
                        }
                        catch (SqlException ex)
                        {
                            con.Close();
                            comman.Code = 0;
                            comman.Message = "Problem has been occurred while submitting your data.";
                            js = new JavaScriptSerializer();
                            js.MaxJsonLength = Int32.MaxValue;
                            Context.Response.Write(js.Serialize(comman));
                            return;

                        }

                    }


                }

            }
            catch (SqlException ex)
            {
                //comman.Code = 0;
                //comman.Message = ex.ToString();
                //insertUserMaster
                //var sqlException = ex.InnerException as System.Data.SqlClient.SqlException;

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 0;
                    comman.Message = "Cannot insert duplicate values..";

                }
                else
                {
                    comman.Code = 0;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
        }




        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getFinancialYearMaster(string startFrom)
        {

            JavaScriptSerializer js;
            List<FinancialYearMaster> listUser = new List<FinancialYearMaster>();
            FinancialYearMasterResponce response = new FinancialYearMasterResponce();

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = "select *, " +
                    "CASE WHEN IsDefault = 1 THEN 'badge bg-success' ELSE 'badge bg-danger' END as IsDefaultCss, " +
                    "CASE WHEN IsDefault = 1 THEN 'Active' ELSE 'Inactive' END as IsDefaults " +
                    "from FinancialYearMaster " +
                    "order by FinancialYearID desc" +
                    " OFFSET " + startFrom + " ROWS FETCH NEXT 10 ROWS ONLY ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        FinancialYearMaster condition = new FinancialYearMaster();
                        condition.FinancialYearID = Convert.ToInt32(rdr["FinancialYearID"].ToString());
                        condition.FinancialYear = rdr["FinancialYear"].ToString();
                        condition.AssessmentYear = rdr["AssessmentYear"].ToString();
                        condition.StartDates = Convert.ToDateTime(rdr["StartDate"].ToString()).ToString("dd-MM-yyyy");
                        condition.EndDates = Convert.ToDateTime(rdr["EndDate"].ToString()).ToString("dd-MM-yyyy");
                        condition.IsDefaultCss = rdr["IsDefaultCss"].ToString();
                        condition.IsDefaults = rdr["IsDefaults"].ToString();
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 1;
            response.Message = "Success";
            response.listFinancialYearMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }


