        // View Design Entry Form
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getColorMatchingFormMaster()
        {
            JavaScriptSerializer js;
            List<DesignColorMatchingForm> listUser = new List<DesignColorMatchingForm>();
            DesignColorMatchingFormResponse response = new DesignColorMatchingFormResponse();

            var request = HttpContext.Current.Request;
            DesignColorMatchingForm ilist = new DesignColorMatchingForm();

            ilist.SearchDesignNo = HttpContext.Current.Request.Params["SearchDesignNo"];
            ilist.startFrom = HttpContext.Current.Request.Params["startFrom"];


            if (ilist.SearchDesignNo != "")
            {
                ilist.SearchDesignNo = " and (DEFM.DesignNo LIKE '%" + HttpContext.Current.Request.Params["SearchDesignNo"] + "%') OR  ((CAST(DEFM.DesignerCode as nvarchar(50)) + CAST(DEFM.DesignNo as nvarchar(50))) LIKE '%" + HttpContext.Current.Request.Params["SearchDesignNo"] + "%') ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                //cmd.CommandText = "select PM.* from PartyMaster PM LEFT JOIN CompanyMaster CM ON PM.CompanyId = CM.CompanyId where CM.is_default = '1' and PM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " and PM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1) order by PM.PartyId desc OFFSET " + ilist.startFrom.ToString() + " ROWS FETCH NEXT 10 ROWS ONLY";
                cmd.CommandText = "SELECT * FROM  ( " +
                    " select ROW_NUMBER() OVER (ORDER BY DCM.DesignColorMatchingFormID desc ) row_num,  " +
                    " DCM.*, DEFM.PhotoOfDesign, DEFM.DesignerID, DEFM.DesignerCode, DEFM.DesignNo, DEFM.PickOnLoom," +
                    " DEFM.TotalCard, DEFM.ReedOnLoom, DCMD.MatchingID, DCMD.WarpMatchingID, DCMD.FeederMatchingID" +
                    " from DesignColorMatchingFormMaster DCM" +
                    " LEFT JOIN DesignEntryFormMaster DEFM ON DEFM.DesignEntryFormID = DCM.DesignEntryFormID" +
                    " LEFT JOIN (" +
                    " SELECT  DesignColorMatchingFormID, STRING_AGG(MatchingID, ', ') AS MatchingID," +
                    " STRING_AGG(WarpMatchingID, ', ') AS WarpMatchingID, STRING_AGG(FeederMatchingID, ', ') AS FeederMatchingID " +
                    " FROM  DesignColorMatchingDetails " +
                    " GROUP BY  DesignColorMatchingFormID" +
                    " ) DCMD ON DCMD.DesignColorMatchingFormID =DCM.DesignColorMatchingFormID " +
                    " where DCM.CompanyId = " + Context.Request.Cookies["CompanyID"].Value.Split('=')[1] + " and DCM.FinancialYearID = " + Context.Request.Cookies["FinacialYearDefaultID"].Value.Split('=')[1] + " " +
                    " " + ilist.SearchDesignNo + " " +
                    " ) as t1  WHERE t1.row_num between " + (Convert.ToInt32(ilist.startFrom) + 1) + " and " + (Convert.ToInt32(ilist.startFrom) + 30) + "  order by t1.DesignColorMatchingFormID desc   ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();



                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        DesignColorMatchingForm condition = new DesignColorMatchingForm();
                        condition.DesignColorMatchingFormID = Convert.ToInt32(rdr["DesignColorMatchingFormID"].ToString());
                        condition.DateandTime = Convert.ToDateTime(rdr["DateandTime"].ToString());
                        condition.DateandTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                        condition.PhotoOfDesign = rdr["PhotoOfDesign"].ToString();
                        condition.DesignerID = Convert.ToInt32(rdr["DesignerID"].ToString());
                        condition.DesignerCode = rdr["DesignerCode"].ToString().ToUpper();
                        condition.DesignNo = rdr["DesignNo"].ToString().ToUpper();
                        condition.PickOnLoom = Convert.ToInt32(rdr["PickOnLoom"].ToString());
                        // condition.TotalCard = Convert.ToInt32(rdr["TotalCard"].ToString());
                        condition.ReedOnLoom = rdr["ReedOnLoom"].ToString().ToUpper();
                        //condition.WarpQuality = rdr["WarpQuality"].ToString().ToUpper();
                        condition.MatchingID = rdr["MatchingID"].ToString().ToUpper();
                        condition.WarpMatchingID = rdr["WarpMatchingID"].ToString().ToUpper();
                        condition.FeederMatchingID = rdr["FeederMatchingID"].ToString();
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }


            System.Web.HttpCookie nameCookie = new System.Web.HttpCookie("DesignColorMatchingFormIDs");
            nameCookie.Expires = DateTime.Now.AddDays(-1);
            Context.Response.Cookies.Add(nameCookie);

            response.Code = 200;
            response.Message = "Success";
            response.listDesignColorMatchingForm = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }



        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getColorMatchingFormPaggination()
        {
            JavaScriptSerializer js;
            List<PagginationMaster> listUser = new List<PagginationMaster>();
            PagginationMasterResponse response = new PagginationMasterResponse();

            var request = HttpContext.Current.Request;
            PagginationMaster ilist = new PagginationMaster();

            ilist.SearchString = HttpContext.Current.Request.Params["SearchString"];


            string SearchString = "";
            if (ilist.SearchString != "")
            {
                SearchString = "  and (DEFM.DesignNo LIKE '%" + ilist.SearchString + "%') OR  ((CAST(DEFM.DesignerCode as nvarchar(50)) + CAST(DEFM.DesignNo as nvarchar(50))) LIKE '%" + ilist.SearchString + "%') ";
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = " select COUNT(*) as Total, CAST(ceiling(CAST(COUNT(*) AS DECIMAL(7,2) ) / CAST(30 AS DECIMAL(7,2) )) AS DECIMAL(7,0)) as Paggination  " +
                    //" DCM.*, DEFM.PhotoOfDesign, DEFM.DesignerID, DEFM.DesignerCode, DEFM.DesignNo, DEFM.PickOnLoom," +
                    //" DEFM.TotalCard, DEFM.ReedOnLoom, DCMD.MatchingID" +
                    " from DesignColorMatchingFormMaster DCM" +
                    " LEFT JOIN DesignEntryFormMaster DEFM ON DEFM.DesignEntryFormID = DCM.DesignEntryFormID" +
                    //" LEFT JOIN (" +
                    //" SELECT  DesignColorMatchingFormID, STRING_AGG(MatchingID, ', ') AS MatchingID FROM  DesignColorMatchingDetails " +
                    //" GROUP BY  DesignColorMatchingFormID" +
                    //" ) DCMD ON DCMD.DesignColorMatchingFormID =DCM.DesignColorMatchingFormID " +
                    " where DCM.CompanyId = " + Context.Request.Cookies["CompanyID"].Value.Split('=')[1] + " and DCM.FinancialYearID = " + Context.Request.Cookies["FinacialYearDefaultID"].Value.Split('=')[1] + " " +
                    " " + SearchString + " ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        PagginationMaster condition = new PagginationMaster();
                        condition.Total = Convert.ToInt32(rdr["Total"].ToString());
                        condition.Paggination = Convert.ToInt32(rdr["Paggination"].ToString());
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 1;
            response.Message = "Success";
            response.listPagginationMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }





        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getColorMatchingFormDetails()
        {

            var request = HttpContext.Current.Request;
            DesignColorMatchingFormResponse ilistColorMatchingForm = new DesignColorMatchingFormResponse();

            List<DesignColorMatchingForm> listDesignEntryForm = new List<DesignColorMatchingForm>();
            //SalesOrderResponseClass salesOrderResponseData = new SalesOrderResponseClass();

            DesignColorMatchingForm ilist = new DesignColorMatchingForm();
            string abc = HttpContext.Current.Request.Params["DesignColorMatchingFormID"];
            //ilist.DesignEntryFormID = Convert.ToInt32(HttpContext.Current.Request.Params["DesignEntryFormID"]);
            string lastCharacter = abc.Substring(abc.Length - 6);

            if (lastCharacter != "%3d%3d")
            {
                string InvoiceId = HttpContext.Current.Request.Params["DesignColorMatchingFormID"].Replace("==", "") + "%3d%3d";
                ilist.DesignColorMatchingFormID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
            }
            else
            {
                ilist.DesignColorMatchingFormID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(HttpContext.Current.Request.Params["DesignColorMatchingFormID"])));
            }

            //Upload Cate Master
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = " select DCMFM.*,  " +
                    " DEFM.PhotoOfDesign, DEFM.DesignerID, DEFM.DesignerCode, DEFM.DesignNo, DEFM.PickOnLoom, " +
                    "  DEFM.TotalCard, DEFM.ReedOnLoom, DEFM.WarpQuality, DEFM.DesignCategory " +
                    " from DesignColorMatchingFormMaster DCMFM " +
                    " LEFT JOIN (" +
                    " 	select DEFM.*, WQ.WarpQuality, SM.Sketcher, TM.Type, DCM.DesignCategory " +
                    " 	from DesignEntryFormMaster DEFM" +
                    " 	LEFT JOIN WarpQualityMaster WQ ON WQ.WarpQualityID = DEFM.WarpQualityID" +
                    " 	LEFT JOIN SketcherMaster SM ON SM.SketcherID = DEFM.SketcherID" +
                    " 	LEFT JOIN TypeMaster TM ON TM.TypeID = DEFM.TypeID" +
