                        DEntryForm.PhotoOfDesign = rdr["PhotoOfDesign"].ToString().ToUpper();
                        DEntryForm.DesignerID = Convert.ToInt32(rdr["DesignerID"].ToString());
                        DEntryForm.DesignerCode = rdr["DesignerCode"].ToString().ToUpper();
                        DEntryForm.DesignNo = rdr["DesignNo"].ToString().ToUpper();
