                        DEntryForm.WarpCheckBox = rdr["WarpCheckBox"].ToString().ToUpper();
                        DEntryForm.WeftCheckBox = rdr["WeftCheckBox"].ToString().ToUpper();




                        SqlCommand cmd1 = new SqlCommand();
