            PartyMaster ilist = new PartyMaster();

            CommanResponse comman = new CommanResponse();

            ilist.PartyId = Convert.ToInt32(HttpContext.Current.Request.Params["PartyId"]);

            //get data
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                try
                {
                    cmd.Connection = con;
                    cmd.CommandText = "DELETE FROM PartyMaster WHERE PartyId = " + ilist.PartyId + " and" +
                        " CompanyId = (select CompanyId from CompanyMaster where is_default = 1) and UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " ";
                    con.Open();
                    int i = cmd.ExecuteNonQuery();
                    //con.Close();
                    if (i > 0)
                    {

                        comman.Code = 200;
                        comman.Message = "Record Deleted Successfully.";
                        js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }

                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Failed to delete record.";
                        js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }
                }
                catch (SqlException ex)
                {

                    con.Close();


                    if (ex.Number == 547)
