                        cmd.CommandType = System.Data.CommandType.Text;



                        string sql = String.Format("Insert Into YarnRequirementMaster  (DateandTime, UserAccountId, CompanyId, FinancialYearID, RequirementDate, RequirementNo, PartyId) OUTPUT INSERTED.YarnRequirementID Values " +
                                           " ('" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', '" + UserAccountId + "', '" + CompanyId + "', '" + FinancialYearID + "', '" + DateTime.ParseExact(myDetails.RequirementDates, "dd/MM/yyyy", CultureInfo.InvariantCulture).ToString("yyyy-MM-dd") + "', '" + myDetails.RequirementNo + "', " +
                                           " '" + myDetails.PartyId + "' )");

                        cmd.CommandText = sql;

                        con.Open();
                        Int64 id = Convert.ToInt64(cmd.ExecuteScalar());

                        //con.Close();
                        if (id > 0)
                        {
                            if (myDetails.listYarnRequirementDetail.Count > 0)
                            {
                                foreach (YarnRequirementDetail each in myDetails.listYarnRequirementDetail)
                                {

                                    string sqls = String.Format("Insert Into YarnRequirementDetail  (DateandTime, UserAccountId, YarnRequirementID, YarnMaterialID, YarnColorID, CompanyName, CompanyColourCode, NoofBoxes) Values  " +
                                           " ( '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', '" + UserAccountId + "', '" + id + "' , '" + each.YarnMaterialID + "', '" + each.YarnColorID + "' , " +
                                           "  '" + each.CompanyName + "', '" + each.CompanyColourCode + "', '" + each.NoofBoxes + "' )");

                                    cmd.CommandText = sqls;
                                    cmd.ExecuteNonQuery();

                                }
                            }


                            con.Close();

                            comman.id = Convert.ToInt32(id);
                            comman.Code = 200;
                            comman.Message = "Record has been saved successfully";

                        }
                        else
                        {
                            comman.Code = 500;
                            comman.Message = "Problem has been occurred while submitting your data.";

                        }
                        cmd.Dispose();
                        con.Close();

                    }
