                    {
                        SqlCommand cmd = new SqlCommand();
                        cmd.Connection = con;
                        cmd.CommandType = System.Data.CommandType.Text;



                        string sql = String.Format("Update YarnRequirementMaster set DateandTime = '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', UserAccountId = '" + UserAccountId + "', CompanyId = (select CompanyId from CompanyMaster where is_default = 1), FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)," +
                            "  RequirementDate = '" + DateTime.ParseExact(myDetails.RequirementDates, "dd/MM/yyyy", CultureInfo.InvariantCulture).ToString("yyyy-MM-dd") + "', RequirementNo = '" + myDetails.RequirementNo + "', PartyId = '" + myDetails.PartyId + "' where YarnRequirementID = '" + myDetails.YarnRequirementID + "' ");

                        cmd.CommandText = sql;

                        con.Open();
                        //Int64 id = Convert.ToInt64(cmd.ExecuteScalar());
                        cmd.ExecuteNonQuery();
                        Int64 id = Convert.ToInt64(myDetails.YarnRequirementID);

                        //con.Close();
                        if (id > 0)
                        {



                            if (myDetails.DeleteYarnDetailsArray != "")
                            {
                                string sqld = String.Format("delete from YarnRequirementDetail where YarnRequirementDetailID in (" + myDetails.DeleteYarnDetailsArray + ") ");
                                cmd.CommandText = sqld;
                                cmd.ExecuteNonQuery();
                            }



                            if (myDetails.listYarnRequirementDetail.Count > 0)
                            {
                                foreach (YarnRequirementDetail each in myDetails.listYarnRequirementDetail)
                                {

                                    if (each.YarnRequirementDetailID == 0)
                                    {
                                        string sqls = String.Format("Insert Into YarnRequirementDetail  (DateandTime, UserAccountId, YarnRequirementID, YarnMaterialID, YarnColorID, CompanyName, CompanyColourCode, NoofBoxes) Values  " +
                                          " ( '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', '" + UserAccountId + "', '" + id + "' , '" + each.YarnMaterialID + "', '" + each.YarnColorID + "' , " +
                                          "  '" + each.CompanyName + "', '" + each.CompanyColourCode + "', '" + each.NoofBoxes + "' )");

                                        cmd.CommandText = sqls;
                                        cmd.ExecuteNonQuery();
                                    }
                                    else
                                    {
                                        string sqls = String.Format("update YarnRequirementDetail set DateandTime = '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', UserAccountId = '" + UserAccountId + "', " +
                                            " YarnRequirementID = '" + id + "', YarnMaterialID = '" + each.YarnMaterialID + "', YarnColorID = '" + each.YarnColorID + "', CompanyName = '" + each.CompanyName + "', " +
                                            " CompanyColourCode = '" + each.CompanyColourCode + "', NoofBoxes = '" + each.NoofBoxes + "' where YarnRequirementDetailID = '" + each.YarnRequirementDetailID + "'  ");

                                        cmd.CommandText = sqls;
                                        cmd.ExecuteNonQuery();
                                    }



                                }
                            }


                            con.Close();

                            comman.id = Convert.ToInt32(id);
                            comman.Code = 200;
                            comman.Message = "Record has been saved successfully";

                        }
                        else
                        {
                            comman.Code = 500;
                            comman.Message = "Problem has been occurred while submitting your data.";

                        }
                        cmd.Dispose();
                        con.Close();

                    }
                }
                catch (SqlException ex)
                {
                    //comman.Code = 0;
                    //comman.Message = ex.ToString().ToUpper();
                    //insertUserMaster
                    //var sqlException = ex.InnerException as System.Data.SqlClient.SqlException;

                    if (ex.Number == 2601 || ex.Number == 2627)
                    {
                        comman.Code = 405;
                        comman.Message = "This Invoice No is already exists.";

                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Problem has been occurred while submitting your data.";

                    }

                }
            }





            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }

