                            if (rdr.HasRows)
                            {
                                while (rdr.Read())
                                {
                                    idDone = 1;
                                }
                            }






                            if (idDone == 0)
                            {




                                if (request.Files.Count > 0)
                                {

                                    var photo1 = request.Files["PhotoOfInward"];
                                    if (photo1 != null && photo1.ContentLength != 0)
                                    {
                                        PhotoOfInward = "PhotoOfInward/" + RandomString(6, true) + photo1.FileName;
