            {
                //ilist.SearchRequirementNo = " and (YPM.PONo LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or SPM.PartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or BPM.PartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or CPM.PartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or SPPM.PartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' ) ";
                ilist.SearchRequirementNo = " AND (YPM.PONo LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' OR YPM.SupplierPartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' " +
                    " OR YPM.BillToPartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' OR YPM.CompanyPartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' " +
                    " OR YPM.GodownTitle LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' OR YMM.YarnMaterial LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' OR YCM.YarnColor LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' ) ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
