                        //condition.SupplierGSTIN = rdr["SupplierGSTIN"].ToString().ToUpper();
                        //condition.SupplierPanNo = rdr["SupplierPAN"].ToString().ToUpper();
                        //condition.SupplierState = rdr["SupplierState"].ToString().ToUpper();
                        //condition.SupplierCity = rdr["SupplierCity"].ToString().ToUpper();
                        //condition.SupplierPincode = rdr["SupplierPincode"].ToString().ToUpper();
