        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnInwardDetails()
        {

            var request = HttpContext.Current.Request;
            YarnInwardMasterResponce listYarnInwardMasterR = new YarnInwardMasterResponce();

            List<YarnInwardMaster> listYarnInwardMaster = new List<YarnInwardMaster>();
            //SalesOrderResponseClass salesOrderResponseData = new SalesOrderResponseClass();

            YarnInwardMaster ilist = new YarnInwardMaster();
            string abc = HttpContext.Current.Request.Params["YarnInwardID"];
            //ilist.DesignEntryFormID = Convert.ToInt32(HttpContext.Current.Request.Params["DesignEntryFormID"]);
            string lastCharacter = abc.Substring(abc.Length - 6);

            if (lastCharacter != "%3d%3d")
            {
                string InvoiceId = HttpContext.Current.Request.Params["YarnInwardID"].Replace("==", "") + "%3d%3d";
                ilist.YarnInwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
            }
            else
            {
                ilist.YarnInwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(HttpContext.Current.Request.Params["YarnInwardID"])));
            }

            //Upload Cate Master
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText =
                    " select  " +
                    "  YIM.*, YPO.ShippedToPartyName, YPO.SupplierPartyName, YPO.BillToPartyName, YPO.CompanyPartyName, YPO.SupplierMobileNo, YPO.ShippedToBillingAddress," +
                    " YMM.YarnMaterial, YCM.YarnColor, YPD.CompanyCode, GM.GodownTitle, GM.GodownAddress, YPM.PONo" +
                    " from YarnInwardMaster YIM" +
                    " LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID" +
                    " LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID =  YCM.YarnColorID " +
                    " LEFT JOIN YarnPODetails YPD ON YIM.YarnPODetailIDCompanyCode =  YPD.YarnPODetailID " +
                    " LEFT JOIN GodownMaster GM ON YIM.GodownID = GM.GodownID" +
                    " LEFT JOIN YarnPOMaster YPM ON YPM.YarnPOID = YIM.YarnPOID" +
                    " LEFT JOIN (select YPM.YarnPOID, SPPM.PartyName as 'ShippedToPartyName', SPM.PartyName as 'SupplierPartyName', BPM.PartyName as 'BillToPartyName'," +
                    " CPM.PartyName as 'CompanyPartyName', SPM.MobileNo as 'SupplierMobileNo'," +
                    "CASE WHEN SPPM.ShippingAddress IS NULL THEN SPPM.BillingAddress ELSE SPPM.ShippingAddress END as 'ShippedToBillingAddress'" +
                    " from YarnPOMaster YPM" +
                    " LEFT JOIN PartyMaster SPM ON YPM.SupplierPartyID = SPM.PartyId" +
                    " LEFT JOIN PartyMaster BPM ON YPM.BillToPartyID = BPM.PartyId" +
                    " LEFT JOIN PartyMaster CPM ON YPM.CompanyPartyID = CPM.PartyId" +
                    " LEFT JOIN PartyMaster SPPM ON YPM.ShippedToPartyID = SPPM.PartyId) as YPO ON YIM.YarnPOID = YPO.YarnPOID" +
                    " where YIM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)" +
                    " AND YIM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)" +
                    " AND YIM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " " +
                    " AND YIM.YarnInwardID = '" + ilist.YarnInwardID + "'  ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();


                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnInwardMaster condition = new YarnInwardMaster();
                        condition.YarnInwardID = Convert.ToInt32(rdr["YarnInwardID"].ToString());
                        condition.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"].ToString());
                        condition.YarnInwardDate = Convert.ToDateTime(rdr["YarnInwardDate"].ToString());
                        condition.ChallanDate = Convert.ToDateTime(rdr["ChallanDate"].ToString());
                        condition.DateAndTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                        condition.YarnInwardDates = Convert.ToDateTime(rdr["YarnInwardDate"].ToString()).ToString("dd-MM-yyyy");
                        condition.ChallanDates = Convert.ToDateTime(rdr["ChallanDate"].ToString()).ToString("dd-MM-yyyy");
                        condition.ChallanNo = Convert.ToInt32(rdr["ChallanNo"].ToString());
                        condition.PartyChallanNo = rdr["PartyChallanNo"].ToString().ToUpper();
                        condition.YarnPOID = Convert.ToInt32(rdr["YarnPOID"].ToString());
                        condition.YarnPoNo = Convert.ToInt32(rdr["PONo"].ToString());
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnPODetailIDCompanyCode = Convert.ToInt32(rdr["YarnPODetailIDCompanyCode"].ToString());
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();
                        condition.ColourCode = rdr["CompanyCode"].ToString().ToUpper();
                        condition.LotNo = rdr["LotNo"].ToString().ToUpper();
                        condition.TotalWeight = Convert.ToDecimal(rdr["TotalWeight"].ToString());
                        condition.PendingWeight = Convert.ToDecimal(rdr["PendingWeight"].ToString());
                        condition.POPendingWeight = Convert.ToDecimal(rdr["POPendingWeight"].ToString());
                        condition.GodownID = Convert.ToInt32(rdr["GodownID"].ToString());
                        condition.GodownTitle = rdr["GodownTitle"].ToString().ToUpper();
                        condition.GodownAddress = rdr["GodownAddress"].ToString().ToUpper();
                        condition.ShippedToName = rdr["ShippedToPartyName"].ToString().ToUpper();
                        condition.SupplierName = rdr["SupplierPartyName"].ToString().ToUpper();
                        condition.BillToPartyName = rdr["BillToPartyName"].ToString().ToUpper();
                        condition.CompanyName = rdr["CompanyPartyName"].ToString().ToUpper();
                        condition.MobileNo = rdr["SupplierMobileNo"].ToString().ToUpper();
                        condition.ShippedtoAddress = rdr["ShippedToBillingAddress"].ToString().ToUpper();
                        condition.PhotoOfInward = rdr["PhotoOfInward"].ToString().ToUpper();




                        SqlCommand cmd1 = new SqlCommand();
                        cmd1.Connection = con;
                        cmd1.CommandType = System.Data.CommandType.Text;
                        cmd1.CommandText = " select YID.*, GLM.LocationTitle from YarnInwardDetail YID  " +
                            " LEFT JOIN GodownLocationMaster GLM ON GLM.GodownLocationID = YID.GodownLocationID " +
                            " where YID.YarnInwardID = '" + ilist.YarnInwardID + "' ";
                        SqlDataReader rdr1 = cmd1.ExecuteReader();

                        if (rdr1.HasRows)
                        {
                            List<YarnInwardDetail> YarnInwardDetail = new List<YarnInwardDetail>();
                            while (rdr1.Read())
                            {
                                YarnInwardDetail YarnPOD = new YarnInwardDetail();
                                YarnPOD.YarnInwardDetailID = Convert.ToInt32(rdr1["YarnInwardDetailID"]);
                                condition.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"].ToString());
                                condition.DateAndTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                                YarnPOD.BoxNo = rdr1["BoxNo"].ToString().ToUpper();
                                YarnPOD.BarcodeNo = rdr1["BarcodeNo"].ToString().ToUpper();
                                YarnPOD.NetWeight = Convert.ToDecimal(rdr1["NetWeight"]);
                                YarnPOD.GodownLocationID = Convert.ToInt32(rdr1["GodownLocationID"]);
                                YarnPOD.LocationTitle = rdr1["LocationTitle"].ToString().ToUpper();

                                YarnInwardDetail.Add(YarnPOD);
                            }
                            condition.listYarnInwardDetail = YarnInwardDetail;
                        }

                        rdr1.Close();
                        cmd1.Dispose();

                        listYarnInwardMaster.Add(condition);

                    }

                    listYarnInwardMasterR.Code = 200;
                    listYarnInwardMasterR.Message = "Success";
                    listYarnInwardMasterR.listYarnInwardMaster = listYarnInwardMaster;
                }
                else
                {
                    listYarnInwardMasterR.Code = 105;
                    listYarnInwardMasterR.Message = "Opps! Purchase Order Not Exist.";
                    listYarnInwardMasterR.listYarnInwardMaster = listYarnInwardMaster;
                }
                con.Close();
            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(listYarnInwardMasterR));
            return;


        }

