            //ilist.YarnInwardDetailIDss = HttpContext.Current.Request.Params["YarnInwardDetailIDss"];
            ilist.siftGodownInputBox = HttpContext.Current.Request.Params["siftGodownInputBox"];

            string CompanyName = "";
